    29	    public CheckoutService(ProductRepository productRepository, OrderRepository orderRepository,
    30	                          ShippingService shippingService, CouponService couponService,
    31	                          ClubService clubService, PaymentService paymentService) {
    32	        this.productRepository = productRepository;
    33	        this.orderRepository = orderRepository;
    34	        this.shippingService = shippingService;
    35	        this.couponService = couponService;
    36	        this.clubService = clubService;
    37	        this.paymentService = paymentService;
