    40	    public CheckoutSummary calculateSummary(CheckoutRequest request, Connection conn) throws SQLException {
    41	        validateRequest(request, conn);
    42	
    43	        Set<String> skus = new HashSet<>();
    44	        for (OrderItem item : request.getItems()) {
    45	            skus.add(item.getSku());
    46	        }
    47	        Map<String, Product> products = productRepository.findBySkus(skus);
    48	
    49	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
    50	
    51	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), products);
    52	
    53	        ShippingService.ShippingQuote shipping = shippingService.calculateShipping(
    54	                request.getShippingMethod(), request.getZipCode(), totalWeight, request.getRegion());
    55	
    56	        BigDecimal shippingCost = shipping.cost;
    57	        int deliveryDays = shipping.deliveryDays;
    58	
    59	        if (clubService.hasFreeShipping(request.getClubTier())
    60	                && request.getShippingMethod() != ShippingMethod.COURIER) {
    61	            shippingCost = BigDecimal.ZERO;
    62	        }
    63	
    64	        boolean isFirstPurchase = false;
    65	        if (conn != null) {
    66	            long paidOrders = orderRepository.countPaidOrdersByCpf(conn, request.getCustomer().getCpf());
    67	            isFirstPurchase = paidOrders == 0;
    68	        }
    69	
    70	        BigDecimal couponDiscount = BigDecimal.ZERO;
    71	        if (request.getCoupon() != null) {
    72	            BigDecimal discount = couponService.calculateDiscount(
    73	                    request.getCoupon(), productsSubtotal, shippingCost, request.getItems(),
    74	                    products, request.getShippingMethod(), isFirstPurchase);
    75	
    76	            if (discount == null) {
    77	                throw new BusinessException("COUPON_NOT_APPLICABLE", 422);
    78	            }
    79	
    80	            couponDiscount = discount;
    81	        }
    82	
    83	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
    84	
    85	        BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
    86	
    87	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
    88	
    89	        PaymentService.PaymentCalculation payment = paymentService.calculatePayment(
    90	                request.getPaymentMethod(), orderTotal, installments,
    91	                request.getCoupon(), couponDiscount);
    92	
    93	        BigDecimal nextPurchaseCredit = clubService.calculateCredit(request.getClubTier(), productsSubtotal);
    94	        boolean gift = clubService.hasGift(request.getClubTier(), productsSubtotal);
    95	
    96	        CheckoutSummary summary = new CheckoutSummary();
    97	        summary.setProductsSubtotal(productsSubtotal);
    98	        summary.setCouponDiscount(couponDiscount);
    99	        summary.setShippingCost(shippingCost);
   100	        summary.setDeliveryDays(deliveryDays);
   101	        summary.setInsurance(insurance);
   102	        summary.setPaymentAdjustment(payment.adjustment);
   103	        summary.setFinalTotal(payment.finalTotal);
   104	        summary.setInstallments(payment.installments);
   105	        summary.setInstallmentAmount(payment.installmentAmount);
   106	        summary.setNextPurchaseCredit(nextPurchaseCredit);
   107	        summary.setGift(gift);
   108	
   109	        return summary;
   110	    }
