   112	    private void validateRequest(CheckoutRequest request, Connection conn) throws SQLException {
   113	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null
   114	                || request.getCustomer().getEmail() == null) {
   115	            throw new BusinessException("INVALID_ORDER", 422);
   116	        }
   117	
   118	        if (request.getItems() == null || request.getItems().isEmpty()) {
   119	            throw new BusinessException("INVALID_ORDER", 422);
   120	        }
   121	
   122	        Set<String> seenSkus = new HashSet<>();
   123	        for (OrderItem item : request.getItems()) {
   124	            if (item.getSku() == null || item.getQuantity() <= 0) {
   125	                throw new BusinessException("INVALID_ORDER", 422);
   126	            }
   127	            if (seenSkus.contains(item.getSku())) {
   128	                throw new BusinessException("INVALID_ORDER", 422);
   129	            }
   130	            seenSkus.add(item.getSku());
   131	        }
   132	
   133	        Map<String, Product> products = productRepository.findBySkus(seenSkus);
   134	        for (OrderItem item : request.getItems()) {
   135	            Product product = products.get(item.getSku());
   136	            if (product == null) {
   137	                throw new BusinessException("UNKNOWN_PRODUCT", 422);
   138	            }
   139	            if (product.isDiscontinued()) {
   140	                throw new BusinessException("PRODUCT_DISCONTINUED", 422);
   141	            }
   142	            if (product.getStock() < item.getQuantity()) {
   143	                throw new BusinessException("INSUFFICIENT_STOCK", 422);
   144	            }
   145	        }
   146	
   147	        if (request.getClubTier() == null) {
   148	            throw new BusinessException("INVALID_CLUB_TIER", 422);
   149	        }
   150	
   151	        if (request.getRegion() == null) {
   152	            throw new BusinessException("INVALID_REGION", 422);
   153	        }
   154	
   155	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
   156	            throw new BusinessException("INVALID_ZIP_CODE", 422);
   157	        }
   158	
   159	        if (request.getShippingMethod() == null) {
   160	            throw new BusinessException("INVALID_SHIPPING_METHOD", 422);
   161	        }
   162	
   163	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), products);
   164	        if (request.getShippingMethod() == ShippingMethod.COURIER
   165	                && totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
   166	            throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", 422);
   167	        }
   168	
   169	        if (request.getCoupon() != null) {
   170	        }
   171	
   172	        if (request.getPaymentMethod() == null) {
   173	            throw new BusinessException("INVALID_PAYMENT_METHOD", 422);
   174	        }
   175	
   176	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
   177	        switch (request.getPaymentMethod()) {
   178	            case PIX, BANK_SLIP -> {
   179	                if (installments != 1) {
   180	                    throw new BusinessException("INVALID_INSTALLMENTS", 422);
   181	                }
   182	            }
   183	            case CREDIT_CARD -> {
   184	                if (installments < 1 || installments > 12) {
   185	                    throw new BusinessException("INVALID_INSTALLMENTS", 422);
   186	                }
   187	            }
   188	        }
   189	
   190	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
   191	            BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems(), products);
   192	            ShippingService.ShippingQuote shipping = shippingService.calculateShipping(
   193	                    request.getShippingMethod(), request.getZipCode(), totalWeight, request.getRegion());
   194	            BigDecimal shippingCost = shipping.cost;
   195	            if (clubService.hasFreeShipping(request.getClubTier())
   196	                    && request.getShippingMethod() != ShippingMethod.COURIER) {
   197	                shippingCost = BigDecimal.ZERO;
   198	            }
   199	
   200	            boolean isFirstPurchase = false;
   201	            if (conn != null) {
   202	                long paidOrders = orderRepository.countPaidOrdersByCpf(conn, request.getCustomer().getCpf());
   203	                isFirstPurchase = paidOrders == 0;
   204	            }
   205	
   206	            BigDecimal couponDiscount = BigDecimal.ZERO;
   207	            if (request.getCoupon() != null) {
   208	                BigDecimal discount = couponService.calculateDiscount(
   209	                        request.getCoupon(), productsSubtotal, shippingCost, request.getItems(),
   210	                        products, request.getShippingMethod(), isFirstPurchase);
   211	
   212	                if (discount != null) {
   213	                    couponDiscount = discount;
   214	                }
   215	            }
   216	
   217	            BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
   218	            BigDecimal orderTotal = productsSubtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
   219	
   220	            if (orderTotal.compareTo(new BigDecimal("1000.00")) > 0) {
   221	                throw new BusinessException("PAYMENT_METHOD_UNAVAILABLE", 422);
   222	            }
   223	        }
   224	    }
   225	
   226	    private BigDecimal calculateProductsSubtotal(List<OrderItem> items, Map<String, Product> products) {
   227	        BigDecimal subtotal = BigDecimal.ZERO;
   228	        for (OrderItem item : items) {
   229	            Product product = products.get(item.getSku());
   230	            BigDecimal itemTotal = product.getPrice()
   231	                    .multiply(new BigDecimal(item.getQuantity()))
   232	                    .setScale(2, RoundingMode.HALF_EVEN);
   233	            subtotal = subtotal.add(itemTotal);
   234	        }
   235	        return subtotal;
   236	    }
   237	
   238	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> products) {
   239	        BigDecimal weight = BigDecimal.ZERO;
   240	        for (OrderItem item : items) {
   241	            Product product = products.get(item.getSku());
   242	            BigDecimal itemWeight = product.getWeightKg()
   243	                    .multiply(new BigDecimal(item.getQuantity()));
   244	            weight = weight.add(itemWeight);
   245	        }
   246	        return weight;
   247	    }
   248	
   249	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
   250	        BigDecimal percentage = switch (region) {
   251	            case SOUTHEAST, SOUTH -> new BigDecimal("0.01");
   252	            case MIDWEST -> new BigDecimal("0.015");
   253	            case NORTH -> new BigDecimal("0.025");
   254	            case NORTHEAST -> new BigDecimal("0.02");
   255	        };
   256	
   257	        BigDecimal insurance = productsSubtotal.multiply(percentage)
   258	                .setScale(2, RoundingMode.HALF_EVEN);
   259	
   260	        BigDecimal limit = switch (region) {
   261	            case NORTH, NORTHEAST -> new BigDecimal("30.00");
   262	            case SOUTHEAST, SOUTH, MIDWEST -> null;
   263	        };
   264	
   265	        if (limit != null && insurance.compareTo(limit) > 0) {
   266	            return limit;
   267	        }
   268	
   269	        return insurance;
   270	    }
   271	}
