    11	import java.net.URI;
    12	import java.net.http.HttpClient;
    13	import java.net.http.HttpRequest;
    14	import java.net.http.HttpResponse;
    15	import java.time.Duration;
    16	
    17	public class ShippingService {
    18	    private final String translogUrl;
    19	    private final HttpClient httpClient;
    20	    private final ObjectMapper objectMapper;
    21	
    22	    public ShippingService(String translogUrl) {
    23	        this.translogUrl = translogUrl;
    24	        this.httpClient = HttpClient.newBuilder()
    25	                .connectTimeout(Duration.ofSeconds(2))
    26	                .build();
    27	        this.objectMapper = new ObjectMapper();
    28	    }
    29	
    30	    public static class ShippingQuote {
    31	        public BigDecimal cost;
    32	        public int deliveryDays;
    33	
    34	        public ShippingQuote(BigDecimal cost, int deliveryDays) {
    35	            this.cost = cost;
    36	            this.deliveryDays = deliveryDays;
    37	        }
    38	    }
    39	
    40	    public ShippingQuote calculateShipping(ShippingMethod method, String zipCode, BigDecimal weightKg, Region region) {
    41	        return switch (method) {
    42	            case ECONOMY -> calculateTranslog(zipCode, weightKg, "STD", region, 7);
    43	            case EXPRESS -> calculateTranslog(zipCode, weightKg, "EXP", region, 0);
    44	            case STORE_PICKUP -> new ShippingQuote(BigDecimal.ZERO, 1);
    45	            case COURIER -> new ShippingQuote(new BigDecimal("18.00"), 0);
    46	        };
    47	    }
    48	
    49	    private ShippingQuote calculateTranslog(String zipCode, BigDecimal weightKg, String service, Region region, int baseDays) {
    50	        int weightGrams = weightKg.multiply(new BigDecimal("1000")).intValue();
    51	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
    52	                translogUrl, zipCode, weightGrams, service);
    53	
    54	        try {
    55	            HttpRequest request = HttpRequest.newBuilder()
    56	                    .uri(URI.create(url))
    57	                    .timeout(Duration.ofSeconds(2))
    58	                    .GET()
    59	                    .build();
    60	
    61	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
    62	
    63	            if (response.statusCode() != 200) {
    64	                throw new BusinessException("CARRIER_UNAVAILABLE", 503);
    65	            }
    66	
    67	            JsonNode json = objectMapper.readTree(response.body());
    68	
    69	            if (json.has("error") && "ZIP_NOT_SERVED".equals(json.get("error").asText())) {
    70	                throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", 422);
    71	            }
    72	
    73	            int priceCents = json.get("price_cents").asInt();
    74	            int etaHours = json.get("eta_hours").asInt();
    75	
    76	            BigDecimal cost = new BigDecimal(priceCents)
    77	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
    78	
