    64	                throw new BusinessException("CARRIER_UNAVAILABLE", 503);
    65	            }
    66	
    67	            JsonNode json = objectMapper.readTree(response.body());
    68	
    69	            if (json.has("error") && "ZIP_NOT_SERVED".equals(json.get("error").asText())) {
    70	                throw new BusinessException("SHIPPING_METHOD_UNAVAILABLE", 422);
    71	            }
    72	
    73	            int priceCents = json.get("price_cents").asInt();
    74	            int etaHours = json.get("eta_hours").asInt();
    75	
    76	            BigDecimal cost = new BigDecimal(priceCents)
    77	                    .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN);
    78	
    79	            int deliveryDays = (int) Math.ceil((double) etaHours / 24);
    80	
    81	            int additionalDays = switch (region) {
    82	                case NORTH -> 3;
    83	                case NORTHEAST -> 2;
    84	                default -> 0;
    85	            };
    86	
    87	            return new ShippingQuote(cost, deliveryDays + additionalDays);
    88	
    89	        } catch (BusinessException e) {
    90	            throw e;
    91	        } catch (Exception e) {
    92	            throw new BusinessException("CARRIER_UNAVAILABLE", 503);
    93	        }
    94	    }
    95	}

